#include <stdio.h>
#include <stdlib.h>
#define MAXLINES 5
int main() {
  char *lineptr[MAXLINES];
  lineptr[0] = (char *) malloc(100 * sizeof(char));
  strcpy(lineptr[0], "This is line 1.");
  lineptr[1] = (char *) malloc(50 * sizeof(char));
  strcpy(lineptr[1], "Line 2.");
  // ... allocate and copy more lines ...
  for (int i = 0; i < 2; i++) {
    printf("%s\n", lineptr[i]);
    free(lineptr[i]);
  }
  return 0;
}
